// in-memory token bucket, one entry per key
const buckets = new Map();

function allow(key, capacity, refillPerSec) {
  const now = Date.now();
  let b = buckets.get(key);
  if (!b) { b = { tokens: capacity, last: now }; buckets.set(key, b); }

  const elapsedSec = (now - b.last) / 1000;
  b.tokens = b.tokens + elapsedSec * refillPerSec;   // refill
  b.last = now;

  if (b.tokens >= 1) {
    b.tokens -= 1;
    return true;
  }
  return false;
}
